def parse_temperature(s):
    unit = s[-1]
    value = float(s[:-1])
    if unit == 'F':
        return (value - 32) * 5 / 9
    return value

def parse_file_size(s):
    units = {'B': 1, 'KB': 1024, 'MB': 1024**2, 'GB': 1024**3}
    for unit in ('GB', 'MB', 'KB', 'B'):
        if s.endswith(unit):
            number = s[:-len(unit)]
            return float(number) * units[unit]

import re
def parse_simple_expr(s):
    m = re.match(r'(\d+)([+\-*/])(\d+)', s)
    a, op, b = m.group(1), m.group(2), m.group(3)
    a, b = int(a), int(b)
    if op == '+':
        return a + b
    if op == '-':
        return a - b
    if op == '*':
        return a * b
    return a / b

def parse_url_parts(url):
    scheme, rest = url.split('://', 1)
    if '?' in rest:
        before_q, query = rest.split('?', 1)
    else:
        before_q, query = rest, ''
    if '/' in before_q:
        idx = before_q.index('/')
        host = before_q[:idx]
        path = before_q[idx:]
    else:
        host = before_q
        path = ''
    return {'scheme': scheme, 'host': host, 'path': path, 'query': query}

def parse_currency(s):
    s = s.lstrip('$').replace(',', '')
    return float(s)

def parse_ratio(s):
    a, b = s.split(':')
    return int(a) / int(b)

def roman_to_int(s):
    values = {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
    total = 0
    prev = 0
    for ch in reversed(s):
        v = values[ch]
        if v < prev:
            total -= v
        else:
            total += v
            prev = v
    return total

def parse_score(s):
    a, b = s.split('-')
