def count_unique_tags(s):
    tags = {t.strip() for t in s.split(',')}
    return len(tags)

def parse_version_tuple(s):
    if s.startswith('v'):
        s = s[1:]
    major, minor, patch = s.split('.')
    return (int(major), int(minor), int(patch))

def parse_multiline_kv(s):
    if s == '':
        return {}
    result = {}
    for line in s.split('\n'):
        k, v = line.split(': ', 1)
        result[k] = v
    return result

def parse_env_line(line):
    key, value = line.split('=', 1)
    if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
        value = value[1:-1]
    return (key, value)

def format_duration_minutes(total_minutes):
    if total_minutes == 0:
        return '0m'
    hours = total_minutes // 60
    minutes = total_minutes % 60
    result = ''
    if hours > 0:
        result += f'{hours}h'
    if minutes > 0:
        result += f'{minutes}m'
    return result

def parse_list_range_spec(spec):
    result = set()
    for token in spec.split(','):
        if '-' in token:
            a, b = token.split('-')
            result.update(range(int(a), int(b) + 1))
        else:
            result.add(int(token))
    return sorted(result)
